      {
        "code": "H335",
        "text": "호흡기계 자극을 일으킬 수 있음",
        "line": "p1:L25"
      },
      {
        "code": "H372",
        "text": "장기간 또는 반복노출 되면 신체 중 (...)에 손상을 일으킴",
        "line": "p1:L26"
      }
    ],
    "p_statements": [
      {
        "code": "P260",
        "type": "예방",
        "text": "(분진·흄·가스·미스트·증기·스프레이)를(을) 흡입하지 마시오.",
        "line": "p2:L2"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "(분진·흄·가스·미스트·증기·스프레이)의 흡입을 피하시오.",
        "line": "p2:L3"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급 부위를 철저히 씻으시오.",
        "line": "p2:L4"
      },
      {
        "code": "P270",
        "type": "예방",
        "text": "이 제품을 사용할 때에는 먹거나, 마시거나 흡연하지 마시오.",
        "line": "p2:L5"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p2:L6"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L8"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관(의사)의 진찰을 받으시오.",
        "line": "p2:L9"
      },
      {
        "code": "P314",
        "type": "대응",
        "text": "불편함을 느끼면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L10"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "용기는 환기가 잘 되는 곳에 단단히 밀폐하여 저장하시오.",
        "line": "p2:L12"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오.",
        "line": "p2:L13"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "(관련 법규에 명시된 내용에 따라) 내용물과 용기를 폐기하시오",
        "line": "p2:L15"
      }
    ],
    "nfpa": {
      "health": 2,
